def is_stack_sortable(arr):
    stack = []
    expected = 1
    i = 0

    while i < len(arr) or stack:
        if stack and stack[-1] == expected:
            stack.pop()
            expected += 1
        elif i < len(arr):
            stack.append(arr[i])
            i += 1
        else:
            return False

    return True

