def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Memoization for game states
    memo = {}

    def can_win(state):
        state = tuple(sorted(state))
        if state in memo:
            return memo[state]

        # If all elements are 0, current player loses
        if all(x == 0 for x in state):
            memo[state] = False
            return False

        # Try all possible moves
        # Move 1: Decrease one element by x
        for i in range(len(state)):
            if state[i] > 0:
                for x in range(1, state[i] + 1):
                    new_state = list(state)
                    new_state[i] -= x
                    if not can_win(new_state):
                        memo[state] = True
                        return True

        # Move 2: Decrease all elements by x
        min_val = min(x for x in state if x > 0) if any(x > 0 for x in state) else 0
        for x in range(1, min_val + 1):
            new_state = [val - x for val in state]
            if not can_win(new_state):
                memo[state] = True
                return True

        memo[state] = False
        return False

    if can_win(a):
        print("BitLGM")
    else:
        print("BitAryo")

solve()
