def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def solve(t, w, b):
    if w == b:
        return f"{t}/{t}"

    L = lcm(w, b)

    # Count ties in one complete period [1, L]
    ties_in_period = 0
    for i in range(1, min(L + 1, t + 1)):
        willman_steps = i // w
        bolt_steps = i // b
        if willman_steps == bolt_steps:
            ties_in_period += 1

    if t <= L:
        g = gcd(ties_in_period, t)
        return f"{ties_in_period // g}/{t // g}"

    # For t > L, we have complete periods plus remainder
    complete_periods = t // L
    remainder = t % L

    total_ties = complete_periods * ties_in_period

    # Count ties in the remainder part [1, remainder]
    for i in range(1, remainder + 1):
        willman_steps = i // w
        bolt_steps = i // b
        if willman_steps == bolt_steps:
            total_ties += 1

    g = gcd(total_ties, t)
    return f"{total_ties // g}/{t // g}"

