def max_beauty_after_n_turns(ribbon, n):
    length = len(ribbon)

    # If n >= length, we can make all characters the same
    if n >= length:
        return length

    # Count frequency of each character
    char_count = {}
    for char in ribbon:
        char_count[char] = char_count.get(char, 0) + 1

    # Find the maximum frequency
    max_freq = max(char_count.values())

    # We can increase the max frequency by at most n
    # But we can't exceed the total length
    return min(length, max_freq + n)

