# Parse the string to extract letters and their modifiers
parsed = []
i = 0
while i < len(s):
    if s[i].isalpha():
        letter = s[i]
        modifier = None
        if i + 1 < len(s) and s[i + 1] in ['*', '?']:
            modifier = s[i + 1]
            i += 1
        parsed.append((letter, modifier))
    i += 1

n = len(parsed)

# dp[i][j] = True if we can form a string of length j using first i elements
dp = [[False] * (k + 1) for _ in range(n + 1)]
dp[0][0] = True

for i in range(1, n + 1):
    letter, modifier = parsed[i - 1]

    for j in range(k + 1):
        if not dp[i - 1][j]:
            continue

        if modifier is None:
            # Must use the letter exactly once
            if j + 1 <= k:
                dp[i][j + 1] = True
        elif modifier == '?':
            # Can remove (0 times) or keep (1 time)
            dp[i][j] = True  # remove
            if j + 1 <= k:
                dp[i][j + 1] = True  # keep
        elif modifier == '*':
            # Can remove, keep, or repeat multiple times
            dp[i][j] = True  # remove
            for rep in range(1, k - j + 1):
                if j + rep <= k:
                    dp[i][j + rep] = True

if not dp[n][k]:
    print("Impossible")
else:
    # Reconstruct the solution
    result = []
    i, j = n, k

    while i > 0 and j >= 0:
        letter, modifier = parsed[i - 1]

        if modifier is None:
            # Must have used the letter exactly once
            result.append(letter)
            i -= 1
            j -= 1
        elif modifier == '?':
            # Check if we removed it or kept it
            if dp[i - 1][j]:
                # We removed it
                i -= 1
            else:
                # We kept it
                result.append(letter)
                i -= 1
                j -= 1
        elif modifier == '*':
            # Find how many times we used it
            found = False
            # Try removing first
            if dp[i - 1][j]:
                i -= 1
                found = True
            else:
                # Try different repetition counts
                for rep in range(1, j + 1):
                    if dp[i - 1][j - rep]:
                        for _ in range(rep):
                            result.append(letter)
                        i -= 1
                        j -= rep
                        found = True
                        break

            if not found:
                i -= 1

    result.reverse()
    print(''.join(result))

