import math

def solve(l, r, x, y):
    if y % x != 0:
        return 0

    q = y // x

    # Find all divisor pairs of q
    divisors = []
    for i in range(1, int(math.sqrt(q)) + 1):
        if q % i == 0:
            divisors.append(i)
            if i != q // i:
                divisors.append(q // i)

    count = 0
    for d1 in divisors:
        d2 = q // d1
        if math.gcd(d1, d2) == 1:
            a = x * d1
            b = x * d2
            if l <= a <= r and l <= b <= r:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

