from itertools import permutations, product

def solve():
    n = int(input())
    cubes = []
    for _ in range(n):
        faces = list(map(int, input().split()))
        cubes.append(set(faces))

    def can_make_number(num):
        s = str(num)
        length = len(s)

        if length > n:
            return False

        # Try all permutations of cubes
        for cube_perm in permutations(range(n), length):
            # Try all combinations of faces for selected cubes
            face_combinations = []
            for i in range(length):
                face_combinations.append(list(cubes[cube_perm[i]]))

            for face_combo in product(*face_combinations):
                if ''.join(map(str, face_combo)) == s:
                    return True

        return False

    x = 0
    while True:
        if can_make_number(x + 1):
            x += 1
        else:
            break

    return x

