def solve():
    n = int(input())
    a = list(map(int, input().split()))

    if n == 1:
        if a[0] == 0:
            print("YES")
            print("0")
        else:
            print("NO")
        return

    # For the expression to be false, we need the last implication to be false
    # This means the left part must be true and the right part must be false

    # The rightmost element must be 0 for the result to be false
    if a[-1] == 1:
        print("NO")
        return

    # We need to make the left part true
    # Strategy: group all elements except the last one with left association
    # and make sure this evaluates to true

    def evaluate_left_assoc(arr):
        if len(arr) == 1:
            return arr[0]
        result = arr[0]
        for i in range(1, len(arr)):
            # implication: result -> arr[i]
            if result == 1 and arr[i] == 0:
                result = 0
            else:
                result = 1
        return result

    # Check if we can make the left part (all except last) evaluate to 1
    left_part = a[:-1]
    if evaluate_left_assoc(left_part) == 1:
        print("YES")
        # Build the expression
        expr = str(a[0])
        for i in range(1, n-1):
            expr = "(" + expr + "->" + str(a[i]) + ")"
        expr = "(" + expr + "->" + str(a[-1]) + ")"
        print(expr)
    else:
        print("NO")

