def count_divisible(k, start, end):
    if start > end:
        return 0

    # Find the first multiple of k >= start
    if start >= 0:
        first = ((start + k - 1) // k) * k
    else:
        first = (start // k) * k

    # Find the last multiple of k <= end
    if end >= 0:
        last = (end // k) * k
    else:
        last = ((end - k + 1) // k) * k

    if first > end or last < start:
        return 0

    return (last - first) // k + 1

